# Plain-language layer for readers who are not project managers.
# plain   = what it is, in everyday words
# like    = an everyday comparison
# without = what goes wrong if nobody keeps it
PLAIN = {
    "business-case": ("The argument for spending the money: what it costs, what we get back, and why this option beats the others.",
                      "Like comparing quotes before a home renovation and working out whether it adds enough value to the house.",
                      "Money gets spent on projects nobody can later prove were worth it."),
    "project-charter": ("The official 'go ahead' for the project. It says what we will deliver, by when, for how much, and who is in charge.",
                        "Like the signed agreement with a builder before work starts.",
                        "People disagree later about what was promised, and the project manager has no authority to make calls."),
    "stakeholder-register": ("A list of everyone the project affects or who can affect it, how much they care, and how we'll keep them on side.",
                             "Like a wedding planner's guest list with notes on who needs special attention.",
                             "Someone important gets surprised late and blocks or delays the work."),
    "raci-matrix": ("A grid that shows, for each task, who does it, who signs it off, who gets asked, and who just gets told.",
                    "Like a household chore chart that also says who checks the job was done.",
                    "Work falls between the cracks, or two people both think they're in charge."),
    "project-management-plan": ("The rulebook for running the project: how we'll track time, money, quality and risk, and when we escalate.",
                                "Like the house rules a team agrees before a long trip: who drives, who books, what happens if we're late.",
                                "Everyone runs things their own way and problems get escalated too late, or not at all."),
    "project-schedule-gantt": ("The timeline: every piece of work with start and end dates, drawn as bars so you can see what overlaps and what is late.",
                               "Like a wedding-day timeline, but stretched over months.",
                               "Nobody can see that a delay in one task will push back everything after it."),
    "budget-evm-tracker": ("Tracks money: what we planned to spend by now, what we actually spent, and how much work that money really got done.",
                           "Like checking a renovation: half the budget is gone, but is half the house finished?",
                           "Overspending is noticed only when the money runs out."),
    "resource-capacity-plan": ("Shows how many people of each kind we need each month, compared with how many we actually have.",
                               "Like a restaurant rota: are there enough chefs on Saturday night?",
                               "Some people are overloaded and burn out while work waits for skills nobody booked."),
    "communication-plan": ("Who gets told what, how often and how: weekly emails, monthly meetings, team huddles.",
                           "Like a school's calendar of parent newsletters and meetings.",
                           "Some people feel ignored, others are flooded with updates, and rumours fill the gap."),
    "benefits-register": ("The list of good things the project promised (faster service, more sales) with how we'll measure them and who checks.",
                          "Like noting your electricity bill before installing solar panels, so you can prove the saving afterwards.",
                          "The project finishes but nobody can show it delivered what it promised."),
    "raid-log": ("One place to track what might go wrong (Risks), what we're taking for granted (Assumptions), what is going wrong (Issues), what we're waiting on (Dependencies), and what we decided (Decisions).",
                 "Like a ship captain's log of hazards ahead, problems on board and decisions made.",
                 "Known problems are forgotten until they explode, and old decisions get argued again."),
    "change-log": ("A running list of every request to change the plan and whether it was approved, with the extra cost and time.",
                   "Like the list of extras added to a building contract: 'add a window: +$800, +2 days'.",
                   "Lots of small extras add up to a big overrun nobody agreed to."),
    "change-request-form": ("The form used to ask for one change to the plan. It explains why, what it will cost, and what the alternatives are, so someone can decide.",
                            "Like asking your builder for a quote before agreeing to move a wall.",
                            "Changes slip in through hallway conversations and nobody owns the consequences."),
    "weekly-status-report": ("A one-page weekly update: are we on track (green, amber or red), what got done, what's next, and what help we need.",
                             "Like a weekly school report for the project.",
                             "Leaders find out about problems from rumours, or too late to help."),
    "steering-committee-deck": ("Slides for the monthly meeting with senior leaders who make the big decisions about the project.",
                                "Like a board meeting pack: short, focused on the decisions needed.",
                                "Big decisions get delayed because leaders don't have what they need to decide."),
    "steering-committee-minutes": ("The written record of what senior leaders decided in their meeting and who will do what by when.",
                                   "Like the minutes of a residents' association meeting.",
                                   "People remember decisions differently and agreed actions never happen."),
    "project-health-dashboard": ("A single page of the most important numbers and colours that show at a glance how healthy the project is.",
                                 "Like a car dashboard: speed, fuel and warning lights in one view.",
                                 "People have to dig through many files to know if something is wrong."),
    "agile-sprint-metrics": ("Tracks how much work the team finishes in each two-week cycle (a 'sprint'), so we can predict when the rest will be done.",
                             "Like tracking how many kilometres you run each week to predict when you'll be ready for a marathon.",
                             "Delivery dates are guesses, and teams take on more than they can finish."),
    "quality-delivery-metrics": ("Measures how good and how reliable the software work is: how often it's released, how often releases break, how many bugs are found.",
                                 "Like a factory tracking defects per batch and how quickly the line restarts after a stoppage.",
                                 "Quality problems surface only when customers find them."),
    "program-portfolio-dashboard": ("One view of several related projects together, so leaders can see which need attention.",
                                    "Like an air-traffic control screen showing every plane at once.",
                                    "Leaders can't compare projects or spot a struggling one in time."),
    "uat-signoff-certificate": ("The business's formal 'yes, this works for us' after real users have tested the new system.",
                                "Like the final walk-through of a new house before you accept the keys.",
                                "A system goes live that the people using it never agreed was ready."),
    "go-no-go-checklist": ("The final checklist before launch. Each item must be 'yes' before we switch the new system on.",
                           "Like a pilot's pre-flight checklist.",
                           "Launch happens because the date arrived, not because everything was ready."),
    "cutover-runbook": ("The step-by-step script for launch weekend: who does what, at what time, how we check it worked, and how to undo it if needed.",
                        "Like a stage manager's cue sheet for opening night.",
                        "Launch night becomes improvised, and nobody knows how to roll back if it fails."),
    "lessons-learned-report": ("What went well and what didn't, written down so the next project does better.",
                               "Like a sports team reviewing match footage.",
                               "The organisation repeats the same mistakes on every project."),
    "project-closure-report": ("The final report: what was delivered compared with what was promised, what's been handed over, and confirmation the project can close.",
                               "Like the final handover pack when you move out of a rented flat.",
                               "Loose ends stay open, money stays committed and nobody owns what's left."),
}

for _d in DOCS:
    _d["plain"], _d["like"], _d["without"] = PLAIN[_d["id"]]
